return await (async () => {
  const api = globalThis.dnd5eClasspack;
  if (!api?.push) return ui.notifications.warn("请先启用 ClassPack。");
  const choice = await api.dialog("强制位移", "", [
    ["selectOption", [{ label: "参考点", name: "mode", options: { options: [
      { value: "caster", label: "施法者" }, { value: "region", label: "选中的 Region 或最近的 Region" },
      { value: "point", label: "手动选择" }
    ] } }]],
    ["selectOption", [{ label: "方向", name: "direction", options: { options: [
      { value: "away", label: "远离" }, { value: "toward", label: "靠近" }
    ] } }]],
    ["number", [{ label: "距离（场景单位）", name: "distance", options: { currentValue: 15 } }]],
    ["selectOption", [{ label: "目标", name: "targets", options: { options: [
      { value: "targets", label: "已 target 的 Token" }, { value: "controlled", label: "控制的 Token（除施法者）" }
    ] } }]],
    ["selectOption", [{ label: "动画", name: "animate", options: { options: [
      { value: "yes", label: "播放" }, { value: "no", label: "不播放" }
    ] } }]]
  ], "okCancel");
  if (!choice?.buttons) return;
  const distance = Number(choice.distance);
  if (!Number.isFinite(distance) || distance <= 0) return ui.notifications.warn("请输入大于零的距离。");
  const caster = canvas.tokens.controlled[0] ?? (typeof token === "undefined" ? null : token);
  let origin;
  if (choice.mode === "caster") {
    if (!caster) return ui.notifications.warn("请先控制施法者的 Token。");
    origin = caster;
  } else if (choice.mode === "region") {
    const regions = Array.from(canvas.scene.regions).filter(region => region.object?.visible);
    const selected = canvas.regions.controlled[0]?.document;
    origin = selected ?? regions.sort((a, b) => (b._stats?.createdTime ?? 0) - (a._stats?.createdTime ?? 0))[0];
    if (!origin || origin.shapes.length !== 1) {
      ui.notifications.info("未找到单一形状的 Region，请手动选择参考点。");
      origin = null;
    }
  }
  if (!origin) {
    const point = await api.Crosshairs.showCrosshairs({ timeout: 20000, label: "选择参考点" });
    if (point.cancelled || !point.valid) return;
    origin = point;
  }
  const targets = choice.targets === "targets" ? Array.from(game.user.targets ?? [])
    : canvas.tokens.controlled.filter(target => target.id !== caster?.id);
  if (!targets.length) return ui.notifications.warn("请选择要移动的目标。");
  const result = await api.push(targets, origin, choice.direction === "away" ? distance : -distance,
    { animate: choice.animate === "yes", avoidOccupied: true, checkCollision: true });
  for (const target of targets) {
    if (result[target.id] !== true) ui.notifications.warn(target.name + " 的位移未完成或被阻挡。");
  }
  return result;
})();
